[data-balsa="card"][data-padding="sm"] { --balsa-surface-padding: 1rem; }
[data-balsa="card"][data-padding="md"] { --balsa-surface-padding: 1.25rem; }
[data-balsa="card"][data-padding="lg"] { --balsa-surface-padding: 1.5rem; }

/* ApplicationCard hands Card `padding="none"` and pads its own regions, so the
   inset its body actually uses has to be declared here rather than inferred. */
[data-balsa="card"][data-application-card] { --balsa-surface-padding: 1.25rem; }
[data-balsa="card"][data-application-card][data-size="sm"] { --balsa-surface-padding: 1rem; }
[data-balsa="card"][data-application-card][data-size="lg"] { --balsa-surface-padding: 1.5rem; }

:where(
  [data-balsa="card"],
  [data-balsa="modal-panel"],
  [data-balsa="drawer-panel"],
  [data-balsa="popup-panel"],
  [data-balsa="menu-list"]
) {
  --balsa-shadow-contained: var(--balsa-shadow-detail);
  /* Floored at one base unit, and never above the radius it nests inside.
     The pure subtraction is right and degenerates here: Balsa pads further
     than it curves -- 16px of inset against a 14px surface radius -- so it
     clamps to zero and squares off every contained corner. That proportion is
     not an accident and is shared with shadcn, whose card is a 12px radius with
     24px of padding, so correcting it by growing the radius would pull away
     from the ecosystem Balsa is built on.
     The floor is the documented answer for this case: where the subtraction
     reaches zero, a small inner radius is chosen by eye, typically a few
     pixels. One base unit is that value, expressed as a token rather than as a
     number nobody can trace.
     The upper clamp keeps a square design system square: Brutalism curves by
     0px, and a floor with no ceiling would round its inner corners while its
     outer corners stayed sharp. */
  --balsa-radius-contained: min(
    var(--balsa-radius-surface),
    max(
      var(--balsa-space-unit),
      calc(var(--balsa-radius-surface) - var(--balsa-surface-padding, 0px))
    )
  );
}

/* A bordered surface elevates on its own and stays quiet inside another. Before
   this, none of them elevated at all: `data-shadow` only ever had rules for the
   explicit none/sm/md/lg, and every component defaults to `auto`, which had no
   rule anywhere. */
