  [data-balsa="alert"],
  [data-balsa="table"],
  [data-balsa="scroll-area"],
  [data-balsa="resizable"]
)[data-shadow="auto"] {
  box-shadow: var(--balsa-shadow-contained, var(--balsa-shadow-surface));
}

/* The concentric corner, for a surface that asked for one. `auto` emits no
   radius utility, so this is the only declaration and nothing outranks it. A
   surface with nothing published above it falls back to the ordinary surface
   radius and reads exactly as it did before. */
