  [data-balsa="alert"],
  [data-balsa="table"],
  [data-balsa="scroll-area"],
  [data-balsa="resizable"]
)[data-rounded="auto"] {
  border-radius: var(--balsa-radius-contained, var(--balsa-radius-surface));
}

