  border-radius: var(--balsa-radius-control);
  background: var(--balsa-color-border-strong);
  background-clip: padding-box;
}

[data-balsa="scroll-area"][data-visibility="always"] [data-balsa="scroll-area-viewport"] {
  scrollbar-gutter: stable;
}

[data-balsa="scroll-area"][data-visibility="hover"] [data-balsa="scroll-area-viewport"] {
  scrollbar-color: transparent transparent;
}

[data-balsa="scroll-area"][data-visibility="hover"]:hover [data-balsa="scroll-area-viewport"],
[data-balsa="scroll-area"][data-visibility="hover"]:focus-within [data-balsa="scroll-area-viewport"] {
  scrollbar-color: var(--balsa-color-border-strong) transparent;
}

[data-balsa="scroll-area"][data-visibility="hover"] [data-balsa="scroll-area-viewport"]::-webkit-scrollbar-thumb {
  background-color: transparent;
}

[data-balsa="scroll-area"][data-visibility="hover"]:hover [data-balsa="scroll-area-viewport"]::-webkit-scrollbar-thumb,
[data-balsa="scroll-area"][data-visibility="hover"]:focus-within [data-balsa="scroll-area-viewport"]::-webkit-scrollbar-thumb {
  background-color: var(--balsa-color-border-strong);
}

